import pikepdf

with pikepdf.open('/root/sc100-blank.pdf') as pdf:
    if pdf.Root.AcroForm:
        def explore_fields(field, level=0):
            prefix = "  " * level
            if isinstance(field, list):
                for item in field:
                    explore_fields(item, level)
            elif isinstance(field, dict):
                if '/T' in field:
                    print(f"{prefix}T: {field['/T']}")
                if '/V' in field:
                    print(f"{prefix}V: {field['/V']}")
                if '/Kids' in field:
                    print(f"{prefix}Kids:")
                    explore_fields(field['/Kids'], level + 1)

        print("Field structure:")
        for field in pdf.Root.AcroForm.Fields:
            explore_fields(field)
            print("\n---\n")

